entries[247584] = { ["name"] = "Blitzschlagschild", ["text"] = "190 Mana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit 3 Kugelblitzen, die eine Chance von 50% haben, Nahkampf- oder Distanzangreifer zu treffen und Naturschaden zu verursachen. Jedes Mal, wenn der Blitzschlagschild zuschlägt, löst sich ein Kugelblitz auf. Auf diese Weise erlischt der Schild nach 10 Min. oder nachdem er 3-mal zugeschlagen hat.\n(Procchance: 50%, 3.5s Abklingzeit)" }
entries[247585] = { ["name"] = "Saaten des Chaos", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde beschwört mehrere Saaten des Chaos in der Nähe, die nach 15 Sek. explodieren. Der Schaden der Explosion steigt an, je länger die Saat gewachsen ist.\nSpielercharaktere können die Energie der Kugel absorbieren, indem sie in ihr stehen. Währenddessen erleiden sie jedoch alle 1 Sek. 3161 Schaden." }
