entries[247619] = { ["name"] = "Lichtblutelixier", ["text"] = "Wirken in 2 sek.\nReagenzien:\nAstralwinde (25), Ursargerit , Kristallphiole\nStellt ein Lichtblutelixier her.\nQuest:\nBegrenzte Vorräte\nZone:\nKrokuun\n\nBenutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)" }
entries[247620] = { ["name"] = "Lichtblutelixier", ["text"] = "Wirken in 2 sek.\nReagenzien:\nAstralwinde (20), Kristallphiole\nStellt ein Lichtblutelixier effizienter her.\nWeltquest:\nArbeitsauftrag: Lichtblutelixiere\nZone:\nKrokuun\n\nBenutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)" }
entries[247622] = { ["name"] = "Lichtblutelixier", ["text"] = "Wirken in 2 sek.\nReagenzien:\nAstralwinde (15), Kristallphiole\nChance auf die Herstellung mehrerer Tränke.\nBeruf:\nAlchemie (1)\nEntdeckung:\n\nBenutzen: Erfüllt den Spielercharakter mit Lichtenergie, durch die er Dämonen manchmal zusätzlichen Schaden zufügt. Hält 30 Min. lang an.\n\nKann nur im Freien auf den Verheerten Inseln und Argus verwendet werden. (3 Sek. Abklingzeit)" }
