entries[247679] = { ["name"] = "Todesgriff", ["text"] = "55 Meter Reichweite\nSofort\nMacht sich die unheilige Energie, die alle Materie umgibt und verbindet, zunutze und zieht das Ziel zum Zaubernden hin." }
entries[247680] = { ["name"] = "Tieffrieren", ["text"] = "100 Meter Reichweite\nSofort 3 sek. Abklingzeit\nKanalisiert einen Froststrahl, der das Ziel 3 Sek. lang bewegungsunfähig macht. Wenn der Effekt endet, ist das Ziel mit Eis umhüllt, das es 15 Sek. lang betäubt und ihm 50 Frostschaden zufügt. Wenn das Eis um das Ziel zerstört wird, wird das Ziel befreit." }
entries[247681] = { ["name"] = "Impulsgranate", ["text"] = "Sofort\nIn die Nähe einer Impulsgranate zu kommen, lässt sie explodieren, was 34352 Naturschaden verursacht und alle Spielercharaktere innerhalb von 3 Metern zurückstößt." }
