entries[247688] = { ["name"] = "Tränen der Naaru", ["text"] = "Wirken in 2 sek.\nReagenzien:\nAstralwinde (20), Ursargerit , Kristallphiole\nStellt Tränen der Naaru her.\nQuest:\nAuf der Fährte der Fährtenleser\nZone:\nKrokuun\n\nBenutzen: Zeigt 30 Min. lang den Aufenthaltsort aller in der Nähe befindlichen Dämonen auf der Minikarte an. (3 Sek. Abklingzeit)" }
