entries[247692] = { ["name"] = "Andenkenkontinuum", ["text"] = "Erhöht Eure Chance, eine Andenkenschachtel aus Sanden der Zeit zu erbeuten. Andenkenschachteln enthalten mächtige Gegenstände, die den Schwierigkeitsgrad von Chronoportalherausforderungen stark verringern.\n\nBonus: Erhöht die Bewegungs- und Reitgeschwindigkeit um 10%." }
