entries[248397] = { ["name"] = "Kaltes Herz", ["text"] = "100 Meter Reichweite\nSofort\nGewährt Euch alle 2 Sek. einen Stapel von 'Kaltes Herz', wodurch Euer nächster Einsatz von 'Eisketten' (21% der Angriffskraft) Schattenfrostschaden verursacht. Bis zu 20-mal stapelbar.\n\nWenn Ihr beim Einsatz von 'Eisketten' 20 Stapel von 'Kaltes Herz' habt, wird das Ziel außerdem für 4 Sek. betäubt und in einen Eisblock eingeschlossen." }
